-- Reglas de Bolivia con fuente oficial del SIN: borradores sin verificar (la IA todavía no los usa).
insert into public.ai_knowledge (kind, country_code, topic, title, summary, source_name, source_url, license)
select v.* from (values
  ($k$tax_rule$k$, $k$BO$k$, $k$rts$k$, $k$Régimen Tributario Simplificado (RTS): requisitos y categorías$k$, $k$Según el material del SIN de junio de 2019, el RTS corresponde a personas naturales que son comerciantes minoristas, vivanderos o artesanos, con capital entre Bs 12.001 y Bs 60.000 y ventas anuales de hasta Bs 184.000. Quien supera esos límites pasa al Régimen General. El pago es bimestral y fijo según la categoría de capital: 1 (hasta Bs 15.000): Bs 47; 2 (hasta Bs 18.700): Bs 90; 3 (hasta Bs 23.500): Bs 147; 4 (hasta Bs 29.500): Bs 158; 5 (hasta Bs 37.000): Bs 200; 6 (hasta Bs 60.000): Bs 350. No pueden pertenecer al RTS, entre otros, quienes venden aparatos electrónicos, quienes realizan actividades sujetas al ICE y quienes están en el STI o el RAU. Es un material de 2019: confirme los montos vigentes con el SIN.$k$, $k$SIN – Régimen Tributario Simplificado (material de junio de 2019)$k$, $k$https://www.impuestos.gob.bo/wp-content/uploads/2025/10/RTS-AYMARA-1.pdf$k$, $k$Material informativo del Servicio de Impuestos Nacionales de Bolivia; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$),
  ($k$tax_rule$k$, $k$BO$k$, $k$it$k$, $k$Impuesto a las Transacciones (IT): alícuota, base y declaración$k$, $k$Según el material del SIN, el IT se aplica con una alícuota de 3% sobre los ingresos brutos de la actividad y se declara con el Formulario 400. Los formularios 200 (IVA) y 400 (IT) se presentan de manera mensual, con o sin movimiento. Es un resumen informativo: la base imponible y las exenciones dependen de cada actividad; confirme el tratamiento de su caso con un contador.$k$, $k$SIN – Material informativo para contribuyentes (2025)$k$, $k$https://www.impuestos.gob.bo/wp-content/uploads/2025/10/TEXTO-TRANSPORTE-25.pdf$k$, $k$Material informativo del Servicio de Impuestos Nacionales de Bolivia; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$),
  ($k$tax_rule$k$, $k$BO$k$, $k$iue$k$, $k$Impuesto sobre las Utilidades de las Empresas (IUE): alícuota y declaración$k$, $k$El SIN indica que el IUE se aplica sobre las utilidades obtenidas al cierre de una gestión (año), con una alícuota de 25% sobre la utilidad resultante de los estados financieros, con los ajustes y adecuaciones correspondientes, y se declara con el Formulario 500. El cierre de gestión y el vencimiento dependen del rubro de la empresa: confirme las fechas con un contador.$k$, $k$SIN – Material informativo para contribuyentes (2025)$k$, $k$https://www.impuestos.gob.bo/wp-content/uploads/2025/10/TEXTO-TRANSPORTE-25.pdf$k$, $k$Material informativo del Servicio de Impuestos Nacionales de Bolivia; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$),
  ($k$tax_rule$k$, $k$BO$k$, $k$retenciones$k$, $k$Retenciones de IT, IUE y RC-IVA$k$, $k$El SIN publica las alícuotas de retención con su formulario: Impuesto a las Transacciones (IT), 3%, Formulario 410; Impuesto sobre las Utilidades de las Empresas (IUE), 5%, Formulario 570; Régimen Complementario al IVA (RC-IVA), 13%, Formulario 604. Los formularios se presentan en el SIAT en línea del SIN. Qué operaciones están sujetas a retención y quién debe retener depende de cada caso: confirme con un contador.$k$, $k$SIN – Preguntas frecuentes sobre retenciones (2025)$k$, $k$https://www.impuestos.gob.bo/wp-content/uploads/2025/10/PREGUNTAS-RETENCIONES-25.pdf$k$, $k$Material informativo del Servicio de Impuestos Nacionales de Bolivia; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$),
  ($k$tax_rule$k$, $k$BO$k$, $k$vencimientos$k$, $k$Vencimiento de impuestos mensuales y días no hábiles$k$, $k$Las declaraciones juradas y el pago de los impuestos de liquidación mensual vencen en la fecha que corresponde al último dígito del NIT del contribuyente. Según el material del SIN, si la fecha de vencimiento cae en sábado, domingo o feriado, se traslada al primer día hábil siguiente. El SIN puede prorrogar plazos mediante resoluciones: consulte el calendario vigente en impuestos.gob.bo o con un contador antes de pagar.$k$, $k$SIN – Material informativo para contribuyentes (2025)$k$, $k$https://www.impuestos.gob.bo/wp-content/uploads/2025/10/TEXTO-TRANSPORTE-25.pdf$k$, $k$Material informativo del Servicio de Impuestos Nacionales de Bolivia; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$),
  ($k$tax_rule$k$, $k$BO$k$, $k$prescripcion$k$, $k$Prescripción tributaria tras la Ley 1733$k$, $k$La Ley 1733 de 27 de mayo de 2026 modifica los artículos 59 y 60 del Código Tributario: la Administración dispone de cuatro años para controlar, determinar, sancionar y ejecutar la deuda tributaria, y de dos años para ejecutar sanciones. Se amplían dos años adicionales si el contribuyente no se inscribió o se inscribió en un régimen que no le correspondía. El cómputo inicia el 1 de enero del año siguiente al vencimiento. Confirme con un contador cómo se aplica a cada período.$k$, $k$SIN – Ley 1733 de 27 de mayo de 2026$k$, $k$https://www.impuestos.gob.bo/wp-content/uploads/2026/05/L17332051NCPP.pdf$k$, $k$Material informativo del Servicio de Impuestos Nacionales de Bolivia; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$),
  ($k$tax_rule$k$, $k$BO$k$, $k$consultas$k$, $k$Dónde consultar al SIN$k$, $k$El SIN atiende consultas tributarias por una línea gratuita (800 10 34 44), por chat en línea, por videollamada y en sus plataformas de servicio al contribuyente, y publica la normativa y los formularios en impuestos.gob.bo. Para fines legales rigen siempre las disposiciones oficiales, no los textos informativos.$k$, $k$SIN – Derechos y obligaciones del contribuyente$k$, $k$https://www.impuestos.gob.bo/wp-content/uploads/2025/10/derechosyobligaciones.pdf$k$, $k$Material informativo del Servicio de Impuestos Nacionales de Bolivia; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$)
) as v(kind, country_code, topic, title, summary, source_name, source_url, license)
where not exists (select 1 from public.ai_knowledge k where k.title = v.title);
